#include <iostream>
#include <utility>

bool isSorted(const int list[], int size) {
    for (int i = 0; i < size - 1; ++i) {
        if (list[i] > list[i + 1]) {
            return false;
        }
    }
    return true;
}

int partition(int list[], int size) {
    if (size <= 1) return 0;
    int pivot = list[0];
    int low = 1;
    int high = size - 1;

    while (low <= high) {
        while (low <= high && list[low] <= pivot) {
            low++;
        }
        while (low <= high && list[high] > pivot) {
            high--;
        }
        if (low < high) {
            std::swap(list[low], list[high]);
        }
    }

    std::swap(list[0], list[high]);
    return high;
}

int main() {
    int data[] = {5, 2, 9, 3, 6, 8};
    int n = sizeof(data) / sizeof(data[0]);

    std::cout << "Sorted before: " << (isSorted(data, n) ? "true" : "false") << "\n";
    int pivotIdx = partition(data, n);
    std::cout << "Pivot index: " << pivotIdx << "\n";
    std::cout << "Partitioned array:";
    for (int i = 0; i < n; ++i) {
        std::cout << " " << data[i];
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <cctype>

void count(const char s[], int counts[]) {
    for (int i = 0; i < 26; ++i) counts[i] = 0;
    for (int i = 0; s[i] != '\0'; ++i) {
        unsigned char ch = static_cast<unsigned char>(s[i]);
        if (std::isalpha(ch)) {
            char lower = static_cast<char>(std::tolower(ch));
            counts[lower - 'a']++;
        }
    }
}

void swapCase(const char s1[], char s2[]) {
    int i = 0;
    for (; s1[i] != '\0'; ++i) {
        unsigned char ch = static_cast<unsigned char>(s1[i]);
        if (std::isupper(ch)) {
            s2[i] = static_cast<char>(std::tolower(ch));
        } else if (std::islower(ch)) {
            s2[i] = static_cast<char>(std::toupper(ch));
        } else {
            s2[i] = s1[i];
        }
    }
    s2[i] = '\0'; // Crucial null terminator
}

int main() {
    const char text[] = "Hello World!";
    int counts[26];
    count(text, counts);

    char swapped[64];
    swapCase(text, swapped);
    std::cout << "Swapped: " << swapped << "\n";

    std::cout << "Letter counts:\n";
    for (int i = 0; i < 26; ++i) {
        if (counts[i] > 0) {
            std::cout << static_cast<char>('a' + i) << ": " << counts[i] << " times\n";
        }
    }
    return 0;
}

#include <iostream>
#include <algorithm>

void itoaUse(int value, char s[], int radix) {
    if (value == 0) {
        s[0] = '0';
        s[1] = '\0';
        return;
    }
    bool isNegative = false;
    if (value < 0 && radix == 10) {
        isNegative = true;
        value = -value;
    }

    int i = 0;
    while (value != 0) {
        int rem = value % radix;
        s[i++] = (rem > 9) ? static_cast<char>((rem - 10) + 'a') : static_cast<char>(rem + '0');
        value /= radix;
    }
    if (isNegative) {
        s[i++] = '-';
    }
    s[i] = '\0';
    std::reverse(s, s + i);
}

int main() {
    char binBuf[33];
    char octBuf[33];
    char hexBuf[33];

    int num = 43;
    itoaUse(num, binBuf, 2);
    itoaUse(num, octBuf, 8);
    itoaUse(num, hexBuf, 16);

    std::cout << "Decimal: " << num << "\n";
    std::cout << "Binary : " << binBuf << "\n";
    std::cout << "Octal  : " << octBuf << "\n";
    std::cout << "Hex    : " << hexBuf << "\n";
    return 0;
}
